function rsEsc(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rsMoney(mixed $v):string{return '₹'.number_format((float)$v,0);}
function rsPrice(array $i):float{return (float)($i['display_price']??$i['price']??0);}
function rsImage(?string $p,string $b):?string{return $p?$b.'/'.ltrim($p,'/'):null;}
function rsRating(mixed $id,string $salt=''):array{$n=abs((int)sprintf('%u',crc32($salt.':'.(string)$id)));return [round(4.5+(($n%5)/10),1),70+($n%351)];}
